const fs=require('node:fs'),cp=require('node:child_process');const [command,...args]=process.argv.slice(2);let input='';if(command==='docker'&&args[0]==='exec'&&args.includes('-i'))input=fs.readFileSync(0,'utf8');fs.appendFileSync(process.env.META_DEPLOY_RECORD,JSON.stringify({command,args})+'\n');
if(command==='docker'&&args.includes('migrate')&&args.includes('deploy')&&process.env.META_DEPLOY_MIGRATION_FAIL==='yes')process.exit(1);
if(command==='git'){if(args.includes('rev-parse'))console.log(process.env.META_INBOX_TARGET);else if(args.includes('archive'))process.stdout.write(cp.execFileSync(process.platform==='win32'?'C:/Program Files/Git/usr/bin/tar.exe':'tar',['-cf','-','-C',process.env.META_DEPLOY_REPO,'apps','package.json']));}
else if(command==='df')console.log('Filesystem 1024-blocks Used Available Capacity Mounted\nsynthetic 99999999 1 '+(process.env.META_DEPLOY_LOW_DISK==='yes'?'1024':'99999998')+' 1% /');
else if(command==='curl'){const url=args[args.length-1];if(url.includes('metadata.tencentyun.com'))console.log(process.env.META_DEPLOY_FOREIGN_HOST==='yes'?'ins-foreign':'ins-4jabsxgk');else if(process.env.META_DEPLOY_HEALTH_FAIL==='yes')process.exit(22);else if(args.includes('-w'))process.stdout.write('401');else if(url.endsWith('/health'))console.log('{"status":"ok"}');else if(url.includes('_buildManifest.js'))console.log('synthetic-manifest');else console.log('synthetic-page');}
else if(command==='docker'){if(args[0]==='inspect'){const name=args[args.length-1];console.log(args.some(v=>v.includes('org.opencontainers.image.revision'))?process.env.META_INBOX_TARGET:name.includes('web')?'original-web-image':name.includes('api')?'original-api-image':'protected-worker-unchanged');}else if(args.includes('ps'))console.log('synthetic-'+args[args.length-1]);else if(args[0]==='exec'){if(input.includes('META_INBOX_VERIFY_RUNTIME'))console.log('GATES_CLOSED_AND_MIGRATIONS_PRESENT');else if(input.includes('META_INBOX_VERIFY_CLEANUP'))console.log('INTERNAL_CLEANUP_ACTIVE_PUBLIC_CALLBACKS_CLOSED');else if(input)console.log(JSON.stringify({count:1,digest:process.env.META_DEPLOY_DRIFT==='yes'?'changed':'unchanged'}));else if(args.some(v=>v.includes('BUILD_ID')))console.log('synthetic-build');else console.log('synthetic-manifest');}}
